import React, { useState } from 'react';
import styled from 'styled-components';

const ChatbotContainer = styled.div`
  position: fixed;
  bottom: 20px;
  right: 20px;
  width: 350px;
  max-height: 500px;
  border: 1px solid #ddd;
  border-radius: 10px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
  background: #fff;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  z-index: 1000;
`;

const ChatbotHeader = styled.div`
  background: #007bff;
  color: white;
  padding: 10px;
  text-align: center;
  font-weight: bold;
  cursor: pointer;
`;

const ChatWindow = styled.div`
  flex: 1;
  padding: 10px;
  overflow-y: auto;
  font-size: 0.9rem;
  color: #333;
`;

const ChatInputContainer = styled.div`
  display: flex;
  padding: 10px;
  border-top: 1px solid #ddd;
`;

const ChatInput = styled.input`
  flex: 1;
  padding: 8px;
  border: 1px solid #ddd;
  border-radius: 5px;
  font-size: 1rem;
`;

const SendButton = styled.button`
  padding: 8px 15px;
  margin-left: 10px;
  border: none;
  background-color: #007bff;
  color: white;
  border-radius: 5px;
  cursor: pointer;

  &:hover {
    background-color: #0056b3;
  }
`;

const Chatbot = () => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [isOpen, setIsOpen] = useState(true);

  const predefinedResponses = {
    help: `Here's what I can assist with:
1. Beginner advice: Type "beginner" or "what gear do I need?" 
2. Training tips: Type "training" or "how to train for a triathlon?"
3. Signing up: Type "signup" or "how to sign up?"
4. Race day tips: Type "race day" or "what do I need for race day?"
5. Ask me about specific triathlon gear!`,
    beginner: `Beginner advice:
- Start with a sprint triathlon (shorter distances).
- Basic gear includes a road bike, helmet, goggles, running shoes, and a tri-suit.
- Focus on balanced training across swimming, biking, and running.
- Check out our beginner gear guide in the Equipment section.`,
    training: `Training Tips:
- Plan a weekly schedule that includes swimming, cycling, and running.
- Incorporate rest days to avoid burnout.
- Practice transitions (e.g., swimming to biking, biking to running).
- Gradually increase distances over weeks leading up to your race.`,
    signup: `How to sign up:
- Visit a site like Ironman.com or local triathlon organizations.
- Choose a race that suits your skill level (sprint, Olympic, etc.).
- Register early to secure your spot!
- Check out our 'How to Sign Up' page for step-by-step guidance.`,
    "race day": `Race Day Tips:
- Gear Checklist: Tri-suit, bike, helmet, goggles, running shoes, nutrition (gels), and hydration.
- Lay out your gear in the transition area for quick access.
- Arrive early to get familiar with the course.
- Stay hydrated and pace yourself.`,
  };

  const handleSendMessage = () => {
    if (input.trim() === '') return;

    const userMessage = { sender: 'user', text: input };
    let botResponse;

    // Handle user input intelligently
    const lowerInput = input.toLowerCase();
    if (predefinedResponses[lowerInput]) {
      botResponse = predefinedResponses[lowerInput];
    } else if (lowerInput.includes('gear') || lowerInput.includes('what do i need')) {
      botResponse = predefinedResponses.beginner;
    } else if (lowerInput.includes('train') || lowerInput.includes('training')) {
      botResponse = predefinedResponses.training;
    } else if (lowerInput.includes('sign up') || lowerInput.includes('signup')) {
      botResponse = predefinedResponses.signup;
    } else if (lowerInput.includes('race day')) {
      botResponse = predefinedResponses["race day"];
    } else if (lowerInput.includes('help')) {
      botResponse = predefinedResponses.help;
    } else {
      botResponse = "I'm not sure about that. Try asking for 'help' to see what I can do!";
    }

    const botMessage = { sender: 'bot', text: botResponse };
    setMessages([...messages, userMessage, botMessage]);
    setInput('');
  };

  const toggleChatbot = () => {
    setIsOpen(!isOpen);
  };

  return (
    <ChatbotContainer>
      <ChatbotHeader onClick={toggleChatbot}>
        {isOpen ? 'Triathlon Assistant' : 'Open Chat'}
      </ChatbotHeader>
      {isOpen && (
        <>
          <ChatWindow>
            {messages.map((msg, index) => (
              <p
                key={index}
                style={{
                  textAlign: msg.sender === 'user' ? 'right' : 'left',
                  margin: '5px 0',
                }}
              >
                <strong>{msg.sender === 'user' ? 'You: ' : 'Bot: '}</strong>
                {msg.text}
              </p>
            ))}
          </ChatWindow>
          <ChatInputContainer>
            <ChatInput
              type="text"
              placeholder="Ask me about triathlons!"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
            />
            <SendButton onClick={handleSendMessage}>Send</SendButton>
          </ChatInputContainer>
        </>
      )}
    </ChatbotContainer>
  );
};

export default Chatbot;
